import random
from collections import OrderedDict
rng = random.Random(7)
keys = list(range(1000))
weights = [1 / (i + 1) for i in keys]
reqs = rng.choices(keys, weights, k=20000)
def hit_ratio(cap):
    c, hits = OrderedDict(), 0
    for k in reqs:
        if k in c:
            hits += 1
            c.move_to_end(k)
        else:
            if len(c) >= cap:
                c.popitem(last=False)
            c[k] = 1
    return hits / len(reqs)
for cap in (10, 50, 200, 500):
    r = hit_ratio(cap)
    print('cache %3d of 1000 keys: hit ratio %5.1f%%, average latency %5.1f ms' % (cap, r * 100, r * 1 + (1 - r) * 20))
EOF
