# Three replicas A, B, C. A partition cuts C off. Two clients write to different sides.
def run(mode):
    value = {'A': 1, 'B': 1, 'C': 1}
    written = []
    side_ab, side_c = ['A', 'B'], ['C']
    print('--', mode, 'mode --')
    # client 1 writes x=2 through A (majority side), client 2 writes x=3 through C (isolated)
    for name, nodes, v in (('client1 via A', side_ab, 2), ('client2 via C', side_c, 3)):
        has_majority = len(nodes) >= 2
        if mode == 'CP' and not has_majority:
            print('  %-14s write x=%d  REJECTED (no majority, stays consistent)' % (name, v))
        else:
            for n in nodes:
                value[n] = v
            written.append(v)
            print('  %-14s write x=%d  accepted' % (name, v))
    print('  values during partition:', value)
    if len(written) > 1:
        print('  after healing: conflict, two different writes; last write wins keeps x=3 and loses x=2')
    else:
        print('  after healing: C catches up, every replica has x=%d, nothing lost' % written[0])
run('CP')
run('AP')
EOF
