class Gen:
    def __init__(self, machine):
        self.m, self.last, self.seq = machine, -1, 0
    def next(self, now_ms):
        if now_ms < self.last:
            raise RuntimeError('clock moved backwards: refuse to issue ids')
        if now_ms == self.last:
            self.seq = (self.seq + 1) & 4095
        else:
            self.seq = 0
        self.last = now_ms
        return (now_ms << 22) | (self.m << 12) | self.seq
decode = lambda i: (i >> 22, (i >> 12) & 1023, i & 4095)
g = Gen(7)
ids = [g.next(1000), g.next(1000), g.next(1000), g.next(1001)]
for i in ids:
    print(i, 'ms=%d machine=%d seq=%d' % decode(i))
print('sorted by time:', ids == sorted(ids))
print('max per machine per second:', 4096 * 1000)
try:
    g.next(999)
except RuntimeError as e:
    print('error:', e)
EOF
