cd ~/warm && cat > kv.py <<'EOF'
import os, json
class KV:
    def __init__(self, path):
        self.path, self.mem = path, {}
        if os.path.exists(path):
            for line in open(path):
                op, k, *v = json.loads(line)
                if op == 'put': self.mem[k] = v[0]
                else: self.mem.pop(k, None)
    def _log(self, rec):
        with open(self.path, 'a') as f:
            f.write(json.dumps(rec) + '\n'); f.flush(); os.fsync(f.fileno())
    def put(self, k, v): self._log(['put', k, v]); self.mem[k] = v
    def delete(self, k): self._log(['del', k]); self.mem.pop(k, None)
    def get(self, k): return self.mem.get(k)
    def compact(self):
        tmp = self.path + '.tmp'
        with open(tmp, 'w') as f:
            for k, v in self.mem.items(): f.write(json.dumps(['put', k, v]) + '\n')
        os.replace(tmp, self.path)
if os.path.exists('kv.log'): os.remove('kv.log')
s = KV('kv.log')
for i in range(1000): s.put('counter', i)
s.put('user:7', 'Asha'); s.put('tmp', 'x'); s.delete('tmp')
print('log lines before compaction:', sum(1 for _ in open('kv.log')))
s2 = KV('kv.log')          # simulated crash and restart: rebuild from the log
print('after restart: counter =', s2.get('counter'), ', user:7 =', s2.get('user:7'), ', tmp =', s2.get('tmp'))
s2.compact()
print('log lines after compaction: ', sum(1 for _ in open('kv.log')))
print('data still correct:', KV('kv.log').get('counter'), KV('kv.log').get('user:7'))
EOF
